mapper.select:
SELECT o.* FROM (SELECT T.OWNCENTER, T.RESTYPE, NVL(SUM(T.CPU), '0') || 'C' || NVL(SUM(T.MEMORY), '0') || 'G' || NVL(SUM(T.DISK), '0') || 'G' DESCRIBE, 1 NUM, T.PRICE, SUM(T.TOTALPRICE) TOTALPRICE, T.PX FROM RES_REPORT_INFO T WHERE T.RESTYPE = '虚拟机资源' AND T.RESADDID IN
#{item}
GROUP BY T.OWNCENTER, T.RESTYPE, T.PRICE, T.PX UNION ALL SELECT R.OWNCENTER, R.RESTYPE, R.DESCRIBE, SUM(R.NUM) NUM, R.PRICE, SUM(R.TOTALPRICE) TOTALPRICE, R.PX FROM RES_REPORT_INFO R WHERE R.RESTYPE != '虚拟机资源' AND R.RESADDID IN
#{item}
GROUP BY R.OWNCENTER, R.RESTYPE, R.DESCRIBE, R.PRICE, R.PX ) O ORDER BY O.OWNCENTER
